from __future__ import absolute_import
from future.utils import PY3
__future_module__ = True
if PY3:
    from html import *
else:

    def escape(s, quote=True):
        s = s.replace(b'&', b'&amp;')
        s = s.replace(b'<', b'&lt;')
        s = s.replace(b'>', b'&gt;')
        if quote:
            s = s.replace(b'"', b'&quot;')
            s = s.replace(b"'", b'&#x27;')
        return s


    __all__ = [
     b'escape']
